class SensorFeed implements AsyncDisposable {      // facade over the WebSocket API
  readonly #ws: WebSocket;

  constructor(url: string) { this.#ws = new WebSocket(url); }

  sendFrame(frame: Uint8Array): void { this.#ws.send(frame); }

  async [Symbol.asyncDispose](): Promise<void> {
    this.#ws.close(1000, 'done');                 // one teardown path
  }
}
// await using feed = new SensorFeed(url);

